-- make_seed.py 로 만든 파일입니다. 여러 번 실행해도 안전합니다 (같은 id는 덮어씀).

on conflict (id) do update set name = excluded.name, lat = excluded.lat, lng = excluded.lng, zip = excluded.zip,
  addr = excluded.addr, coord_system = excluded.coord_system, detail_url = excluded.detail_url, base_date = excluded.base_date;
notify pgrst, 'reload schema';
